/**
 *  具名递归类型使 Rust 与 TypeScript 的 JSON 契约保持有限定义。
 *  serde_json::Number 保留传输过程中的整数值。
 */
export type JsonValue =
  | null
  | boolean
  | number
  | null
  | string
  | JsonValue[]
  | { [key in string]: JsonValue };

